def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    my_last, opp_last = history[-1]
    my_last2, opp_last2 = history[-2]

    opp_c_total = 0
    last_cc = -1
    for i in range(n):
        a, b = history[i]
        if b == 'C':
            opp_c_total += 1
        if a == 'C' and b == 'C':
            last_cc = i
    opp_d_total = n - opp_c_total

    start20 = n - 20 if n > 20 else 0
    opp_c_recent = 0
    sucker20 = 0
    for i in range(start20, n):
        a, b = history[i]
        if b == 'C':
            opp_c_recent += 1
        if a == 'C' and b == 'D':
            sucker20 += 1

    start10 = n - 10 if n > 10 else 0
    opp_d10 = 0
    for i in range(start10, n):
        if history[i][1] == 'D':
            opp_d10 += 1

    mutual_d = 0
    for i in range(n - 1, -1, -1):
        a, b = history[i]
        if a == 'D' and b == 'D':
            mutual_d += 1
        else:
            break

    failed = False
    if n >= 3:
        scan_start = 2 if last_cc < 0 else last_cc + 3
        for i in range(scan_start, n):
            if history[i - 2] == ('D', 'D') and history[i - 1] == ('C', 'D') and history[i] == ('C', 'D'):
                failed = True
                break

    rem = 100 - n
    if rem <= 1:
        return 'D'
    if rem == 2:
        if history[-1] == ('C', 'D') and history[-2] == ('D', 'D') and (not failed) and opp_c_recent >= 2:
            return 'C'
        return 'D'

    if history[-1] == ('C', 'D') and history[-2] == ('D', 'D') and (not failed) and opp_c_recent >= 2:
        return 'C'

    if mutual_d >= 3 and (not failed) and opp_c_recent >= 2 and opp_d_total <= opp_c_total + 8:
        return 'C'

    if opp_last == 'D' and opp_last2 == 'D':
        return 'D'

    if sucker20 >= 5 and opp_c_recent <= 12:
        return 'D'
    if opp_d_total > opp_c_total + 8 and opp_c_recent <= 3:
        return 'D'

    if opp_last == 'D':
        if my_last == 'C':
            if sucker20 >= 5 or (sucker20 >= 4 and opp_d10 >= 4):
                return 'D'
            return 'C'
        return 'D'

    return 'C'
